// TH16 v1.00a Extra final spell: st07bs.ecl.txt Boss9:855-892 + BossCard9:2034-2081.
// Dependencies: BossCard9_at 2083-2106, BossCard9_at2 2108-2141, BossCard9_at3 2143-2172.
// Source has no difficulty mask; script is rank 4 (Extra) only.

const TIME_LIMIT: int = 5704;          // 120 shell buffer + 180 Boss9 prep + 5400 spell + 4 startup
const OPENING_BUFFER: int = 120;
const BOSS_Y: fx = 416fx;              // Boss() st07bs.ecl.txt:0019 movePos(0,416) for SPELL_ID 117
const TH16_RICE: int = 480;            // source etSprite type 8, color 6
const BOSS_LASER_COLOR: int = 6;       // source etSprite(2,38,6)

// BossCard9_at2 EX chain: ANIM(recoil kept), OFFSCREEN a=600, INVULN a=700 (no target recipe),
// ANGLE_ACCEL a=540, s=+-0.67deg/frame. Recv recoil is folded into the shot offset below.
xformdef BULLET_SPIRAL(spin: angle) {
    offscreen_keep(600);               // EX OFFSCREEN a=600, b=0
    @540 set_ang_vel(spin);            // ANGLE_ACCEL lasts 540 frames, then stops
    set_ang_vel(0deg);
}

// BossCard9_at3 (2143-2172): one infinite laser at boss+(0,32), width 32 -> target width 16,
// length 512 -> judgment 0.9*512, startup 20 / expand 30 / hold A-32 / shrink 30.
// Constant-width target approximation: warn=20, active=expand+hold+1=A-1, fade=30.
sub card_laser(hold: int, bam_step: int) {
    var a0: angle = 0deg;
    var omega: angle = (0 - bam_step) as angle;
    if $player_x < 0fx {               // unless (PLAYER_X2 < 0): C=pi and B=-B
        a0 = 180deg;
        omega = bam_step as angle;
    }
    var lz: int = laser(BOSS_LASER_COLOR, $self_x, $self_y + 32fx, a0,
                        460.8fx, 16fx, 20, hold - 1, 30);
    wait(60);                          // source laserStAngle loop starts 60 frames after creation
    lz_omega(lz, omega);               // 708 laserStAngle each frame == constant BAM/frame
    wait(hold);
}

// BossCard9_at (2083-2106): wait 600, then ten synchronous laser subcalls separated by wait(60).
async sub card_laser_seq() {
    wait(600);
    card_laser(430, 51);
    wait(60);
    card_laser(430, 55);
    wait(60);
    card_laser(430, 59);
    wait(60);
    card_laser(430, 70);
    wait(60);
    card_laser(390, 72);
    wait(60);
    card_laser(360, 81);
    wait(60);
    card_laser(330, 91);
    wait(60);
    card_laser(300, 100);
    wait(60);
    card_laser(270, 115);
    wait(60);
    card_laser(220, 149);
}

// BossCard9_at2 (2108-2141): 48 shots per cycle from absolute y=448, x stepping by -4*D,
// speed 2.3 at fixed angle, then ANGLE_ACCEL spiral. GI0=96 gives step 4 and 48 shots.
async sub card_bullets(base: angle, side: fx) {
    var back: fx = 9.2fx;                        // ANIM enter: position -= 4*velocity
    var rx: fx = 0fx - back * cos(base);         // fold recoil into the absolute spawn point
    var ry: fx = 448fx - back * sin(base);
    var step_x: fx = (0fx - 4fx) * side;         // E starts 0, -=4; x = E*D
    var spin: angle = 122bam;                    // s = (-1deg*0.67)*D in BAM/frame
    if side > 0fx { spin = (0 - 122) as angle; }
    sh_reset(0);
    sh_sprite(0, TH16_RICE, 6);
    sh_aim(0, 0);                                // etAim(A,1): fixed-direction fan
    sh_ring(0, 0);
    sh_count(0, 1, 1);                           // etCount(A,B=1,1)
    sh_angle(0, base, 30deg);                    // etAngle(A,C,0.5235988)
    sh_speed(0, 2.3fx, 0fx);                     // etSpeed(A,2.3,1.0) with one layer
    sh_xform(0, BULLET_SPIRAL(spin));
    var e: fx = 0fx;
    loop {
        for k in 0..48 {
            sh_offset_abs(0, e + rx, ry);        // etOffsetAbs(A,E*D,448) + ANIM recoil
            sh_fire(0);
            e = e + step_x;
            wait(28);
        }
        e = 0fx;
    }
}

// BossCard9 "+90": both async patterns start together at script time 90.
async sub boss_attack() {
    wait(90);
    spawn card_laser_seq();
    spawn card_bullets(-135deg, 0fx - 1fx);      // at2(0,1,-2.3561945f,-1)
    spawn card_bullets(-45deg, 1fx);             // at2(1,1,-0.7853982f,+1)
    loop { wait(1000); }
}

// Boss9 (855-892) preparation, then BossCard9 spell declaration (2034-2075).
async sub boss_main() {
    set_invuln(65535);                  // shell invulnerability (source setInvuln(180))
    set_hitbox(24fx);                   // Boss() setHitbox(48,48) -> radius 24
    set_hurtbox(20fx);                  // Boss() setHurtbox(40,40) -> radius 20
    move_vel(0, 0deg, 0fx, EASE_LINEAR);              // 404 moveVel(0,0)
    move_to(120, 0fx, BOSS_Y, EASE_QUAD_OUT);         // 401 movePosTime(120,4,0,416)
    wait(180);                          // 0890 wait(180)
    // BossCard9: transition clears/no-op state updates (etCancel/etClear, killAllAsync,
    // enmKillAll, spellEnd, funcSet(0), laserCancel, sound) are covered by the shell.
    move_vel(0, 0deg, 0fx, EASE_LINEAR);              // 2056-2058 stop movement
    set_enemy_flag(ENEMY_NO_BODY, 1);   // 2067 flagSet(3): 0x2 no body; 0x1 no-hit via invuln
    // 2064 setInterrupt(0,0,5400) + 2065 spellEx(117,5400) + 2066 spellTimeout -> survival card.
    spell_begin(0, 117, boss_attack, 5400, 0, SPELL_SURVIVAL, 0);
    wait_spell();
}

// Independent invincible shell: control only handles spawning and has no body.
async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, BOSS_Y, 3000, 0, 0, 0, boss_main);
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
